#!/usr/bin/env node
// Generates src/core/cfg.gen.js: the instruction boundaries of the whole program (docs/TIMING.md §5.3,
// §7 Paso 1.1), for the cycle tracker (src/core/timing.js).
//
// For every instruction of Z_0*.asm, in source order per file: its asm line and, when it does not follow
// the previous instruction directly, its run/load address. Nothing else: no opcodes, operands or other
// ROM bytes. src/core/cfg.js reads opcode, size, cycles and operands from the user's ROM at load time
// (like table()), so the generated file contains only positions, as symbols.js does.
//
// Encoding, per file (base64 of a byte stream):
//   varint (lineDelta << 1 | explicit)           lineDelta = line - previous instruction's line
//   explicit: u16 run, u16 load (little endian)  start of a new block (after data, segment change)
//   not explicit: run/load = previous + previous instruction's size (fallthrough from it)
//
// Usage: node scripts/gen-cfg.mjs [disasmSrcDir] [outFile]
import { writeFileSync } from 'node:fs';
import { join, dirname } from 'node:path';
import { fileURLToPath } from 'node:url';
import { assemble } from './lib/asm65.mjs';

const root = join(dirname(fileURLToPath(import.meta.url)), '..');
const srcDir = process.argv[2] ?? join(root, 'reference/zelda1-disassembly/src');
const outFile = process.argv[3] ?? join(root, 'src/core/cfg.gen.js');

/** Per file (bank 0-7): instructions in source order {line, run, load, size, seg}. */
export function collectInstructions(dir = srcDir) {
  const { statements, segments, problems } = assemble(dir);
  if (problems.length) throw new Error('gen-cfg: layout does not match bins.xml:\n  ' + problems.join('\n  '));
  const files = Array.from({ length: 8 }, () => []);
  for (const [segName, sts] of statements) {
    const seg = segments.get(segName);
    let prevData = false;
    for (const st of sts) {
      if (st.kind === 'ins') {
        const line = Number(/:(\d+)$/.exec(st.where)[1]);
        files[st.file].push({ line, run: st.addr, load: st.loadAddr, size: st.size, seg: segName, order: st.order, mn: st.mn, mode: st.mode, afterData: prevData, bank: seg.bank });
        prevData = false;
      } else if (st.kind === 'data' || st.kind === 'incbin') prevData = true;
    }
  }
  for (const f of files) f.sort((a, b) => a.order - b.order);
  return files;
}

function varint(out, v) {
  while (v >= 0x80) { out.push((v & 0x7f) | 0x80); v >>>= 7; }
  out.push(v);
}

export function encode(files) {
  return files.map((list) => {
    const out = [];
    let prev = null;
    for (const ins of list) {
      const contiguous = prev && !ins.afterData && prev.seg === ins.seg && ins.run === prev.run + prev.size && ins.load === prev.load + prev.size;
      const dl = ins.line - (prev ? prev.line : 0);
      if (dl <= 0) throw new Error(`gen-cfg: lines out of order at Z_0${ins.bank}:${ins.line}`);
      varint(out, (dl << 1) | (contiguous ? 0 : 1));
      if (!contiguous) out.push(ins.run & 0xff, ins.run >> 8, ins.load & 0xff, ins.load >> 8);
      prev = ins;
    }
    return { count: list.length, data: Buffer.from(out).toString('base64') };
  });
}

if (import.meta.main) {
  const files = collectInstructions();
  const enc = encode(files);
  let js = `// GENERATED by scripts/gen-cfg.mjs from the disassembly (Z_0*.asm). Do not edit.
// Instruction boundaries only (asm line + address of each block start); contains no ROM bytes.
// Decoded by src/core/cfg.js with the user's ROM (opcode, size, cycles, operands). See docs/TIMING.md.

/** Per file Z_00..Z_07: { count, data } (base64 varint stream, format in scripts/gen-cfg.mjs). */
export const CFG_FILES = Object.freeze([
`;
  for (const e of enc) js += `  { count: ${e.count}, data: '${e.data}' },\n`;
  js += ']);\n';
  writeFileSync(outFile, js);
  const total = enc.reduce((n, e) => n + e.count, 0);
  console.log(`gen-cfg: ${total} instructions -> ${outFile} (${(js.length / 1024).toFixed(1)} KB)`);
}
